export type Translate = (key: string, params?: Record<string, unknown>) => string;

// Tolgee's `t` echoes the key back when a translation is missing, and the
// vue-i18n instance kept for Quasar components carries no messages, so its
// `$te` is false for every key. Comparing against the key is the only
// reliable existence check in this app.
export function translated(t: Translate, key: string, fallback: string): string {
  const value = t(key);
  return value && value !== key ? value : fallback;
}
